/* ------------------------------------------------------------------ *
 * Clusters de "sistemas instalados" — micro-pontos luminosos.
 * Distribuição orgânica DETERMINÍSTICA (PRNG semeado por cidade) para
 * ser idêntica no servidor e no cliente (sem mismatch de hidratação).
 * ------------------------------------------------------------------ */
function mulberry32(seed: number) {
  return function () {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export type InstallPoint = {
  x: number;
  y: number;
  size: number; // px
  delay: number; // s
  duration: number; // s
};

export type InstallCluster = {
  name: string;
  points: InstallPoint[];
};

function buildCluster(
  seed: number,
  cx: number,
  cy: number,
  count: number,
): InstallPoint[] {
  const rnd = mulberry32(seed * 2654435761);
  const pts: InstallPoint[] = [];
  for (let i = 0; i < count; i++) {
    const ang = rnd() * Math.PI * 2;
    const r = Math.sqrt(rnd()) * 3.6 + 0.7; // raio em % (disco uniforme)
    pts.push({
      x: cx + Math.cos(ang) * r,
      y: cy + Math.sin(ang) * r * 0.96, // viewBox ~quadrado
      size: 3 + rnd() * 3, // 3–6px
      delay: rnd() * 2.2,
      duration: 2 + rnd() * 1.6,
    });
  }
  return pts;
}

export const INSTALL_CLUSTERS: InstallCluster[] = PROJECT_CITIES.map(
  (c, i) => ({
    name: c.name,
    points: buildCluster(i + 1, c.x, c.y, c.systems),
  }),
);

/** total de sistemas representados nos clusters */
export const TOTAL_PLOTTED = PROJECT_CITIES.reduce(
  (s, c) => s + c.systems,
  0,
);

